import{_ as a,a0 as r,w as u,s as l,ao as s,I as p,x as n,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持” | LCTT x X-CMD","titleTemplate":false,"description":"慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持” | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持” | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/Moving a city to Linux requires political backing, says Munich project leader","title":"慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持”","tag":"201404","desc":""},"relativePath":"201404/Moving a city to Linux requires political backing, says Munich project leader.md","filePath":"[post].md"}'),f={name:"201404/Moving a city to Linux requires political backing, says Munich project leader.md"};function x(d,i,m,_,L,T){const t=r("Link");return u(),l("div",null,[i[14]||(i[14]=s('<h1 id="慕尼黑市项目负责人称-将整个城市迁移到-linux-需要政策支持" tabindex="-1">慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持” <a class="header-anchor" href="#慕尼黑市项目负责人称-将整个城市迁移到-linux-需要政策支持" aria-label="Permalink to “慕尼黑市项目负责人称“将整个城市迁移到 Linux 需要政策支持””">​</a></h1><blockquote><p>慕尼黑市政府已将接近 15,000 台 PC 从 Windows NT 操作系统迁移到了其自有的 Linux 发行版</p></blockquote><p>来自IDG 新闻 ： 慕尼黑市十年前开始向 Linux 迁移，今年我们见证了这项工程竣工。“我们学到的最深一课是，你无法在没有持续政策支持的情况下完成这样的项目。”LiMux 项目的负责人 Peter Hofmann 在总结经验时说。</p><p>慕尼黑市政府将他们网络上 15,000 台 PC 中大约 14,800 台迁移到了他们自有的基于 Ubuntu 的 Linux——LiMux 上。这超出了他们原定迁移 12,000 台桌面计算机的计划。</p><p>慕尼黑市是在 Microsoft 声明将不再为 Windows NT 4.0 提供支持的时候决心迁移他们的 IT 系统的，因为他们使用的就是 Windows NT 4.0。当时，该市不得不在迁移到新版 Windows 和寻找一个替代平台之间做出抉择，因为新的软件以及现存软件的新版本都将无法在 Windows NT 上使用。市议会决定与 Linux 携手，和软件供应商们保持更加独立的关系。</p><p>Hofmann 说，政策支持是迁移成功的关键。</p><p>“我们从始至终都拥有政策的支持。我们得让政府官员们时刻掌握项目最新信息，就像对待股东一样。”他说。</p><p>借助这样的手段，这些政客们从未丧失对项目的兴趣，也始终能了解到项目执行人在做什么，他说。“我目睹过很多开源项目流产，”因为它们要么未得到、要么失去了政策支持，他说。</p><p>市政府原定 2009 年完成迁移计划，但事实上从最初作出决定到 LiMux 项目迁移完工大约耗费了十年时间。项目全程也经历了几次延期。</p><p>迁移工作在原计划一年之后才真正开始，这是第一次延期，Hofmann 说。第二次延期缘于 2007 年市议会的一个决定：慕尼黑市的 IT 部门也要负责 Linux 客户端基础设施所必须的标准化工作，他说。但是慕尼黑市既没有正确的程序也没有正确的组织来实现这种标准化，他说。</p><p>项目第三次延期是在 2010 年，当时市议会决定扩大项目规模，Hofmann 说。风险管理、测试管理和需求工程作为三个附加任务目标被加进了项目里。</p><p>尽管困难重重，Hofmann 说他仍然愿意下次再做一次。</p><p>慕尼黑市 IT 组织的异质性基础设施曾是该项目最大的问题之一，Hofmann 说。项目启动之初，22 个组织都有自己独有的配置、软硬件、进程、Windows 客户端知识以及相应投入使用的基础设施，他说。“我们想建设一个标准化的、集中交付和开发的 Linux 客户端，”他说。</p><p>Hofmann 预计，四分五裂的基础设施会造成问题。事实证明，不论从技术因素还是组织因素来看，标准化客户端的工作都比他预想的还要艰难。</p><p>幸运的是，他有足够的自由度重建整个城市的 IT 基础设施。</p><p>“任何人在打算迁移之前都要重新审视他们的整个 IT 组织。迁移到 Linux 远非节省开支和使用免费软件那么简单。”他补充道。</p>',16)),p("p",null,[i[1]||(i[1]=n("但慕尼黑市的迁移工作确确实实省钱了。2012 年 11 月，一名市议员答复道，慕尼黑市计算出迁移到 LiMux 会比更新已有 Microsoft 软件",-1)),o(t,{href:"http://www.itworld.com/operating-systems/321474/switching-linux-saves-munich-over-11-million"},{default:e(()=>[...i[0]||(i[0]=[n("节省超过 1100 万欧元",-1)])]),_:1}),i[2]||(i[2]=n("！",-1))]),i[15]||(i[15]=s("<p>这项计算横向对比了 LiMux、Windows 7 + Microsoft Office、Windows 7 + OpenOffice（慕尼黑市为 LiMux 选择的生产力套件） 三种方案，包含必要的硬件升级、培训、外部迁移支持和优化事务以及其他指标。两个 Windows 方案都明显比 LiMux 方案昂贵很多，这主要缘于微软对软件使用许可收取的费用。</p><p>Hofmann 说，LiMux 不存在支持合同。“你要支持合同干什么？实际上你并没有得到支持，你得到的是新版本。你需要它的唯一理由来自于你的律师，他让你这么做以便日后出现问题有责任人可以追究。我们不追究任何人，我们自己会搞定那些问题，”他说。</p><p>如果慕尼黑市的 IT 人员不能自己修复 bug，他们可以寻求专家解决特定的 bug，Hofmann 说。“你不再依赖从软件供应商那里买来的服务，你依靠你自己和你掌握的信息，”他说。</p><p>尽管这样，抱怨依然存在。从外部组织收到的 Word 和 Excel 文档有时候不得不做些更改再发回去，这样一来会给互通性造成麻烦，他说。慕尼黑市正在说服与他们通信的人员使用 OpenOffice 的 ODF 格式文档，或者对不需要修改的文档使用 PDF 格式，Hofmann 说。慕尼黑市已经借助这一途径协助了互通工具在金融业的推广。</p><p>作为 OpenOffice 迁移计划的一部分，慕尼黑市还开发了 WollMux。这是一个用于模板和表单的 Office 扩展，于 2008 年以自由软件的形式发布，如今已经被少数其他组织采用，他说。</p><p>清除 Microsoft Office 的工作中还存在其他一些障碍——该市内部应用程序对数以千计的 Microsoft Office 和 Visual Basic 宏的依赖就是其中之一，Hofmann 说。</p><p>如今仍然有约 100 个这样的宏在为数不多的 Windows PC 上使用。</p><p>“我们的目标从来都不是彻底清除 Windows，”他说，尽管该市已经超出了迁移 80% PC 的最初目标并且一直运转良好。</p><p>以财政部门为例，三台 Windows PC 仍然在运行特殊的银行软件。如果要迁移到 LiMux，市政府得付钱让软件供应商为这三台机器上运行的应用程序开发 LiMux 版本，Hofmann 说。</p><p>该市与德国政府印刷护照的“联邦印刷”打交道时也面临类似的问题。联邦印刷要求使用一个 Windows 应用程序发送护照所需的个人数据，他说。</p><p>Hofmann 在对这个城市的未来信心满怀的时候也认识到并不是所有人都适合迁移到 Linux。但即使不想迁移到 Linux 的人也一样可以从慕尼黑市的经验中得益：“曾有人对我说，‘从你启动项目那时起，我就可以和 Microsoft 谈判了。’”</p><hr>",12)),p("p",null,[i[4]||(i[4]=n("译自: ",-1)),o(t,{href:"http://www.computerworld.com/s/article/9245353/Moving_a_city_to_Linux_requires_political_backing_says_Munich_project_leader?taxonomyId=122"},{default:e(()=>[...i[3]||(i[3]=[n("http://www.computerworld.com/s/article/9245353/Moving_a_city_to_Linux_requires_political_backing_says_Munich_project_leader?taxonomyId=122",-1)])]),_:1})]),p("p",null,[i[7]||(i[7]=n("译者：",-1)),o(t,{href:"https://github.com/blueabysm"},{default:e(()=>[...i[5]||(i[5]=[n("sailing",-1)])]),_:1}),i[8]||(i[8]=n(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:e(()=>[...i[6]||(i[6]=[n("wxy",-1)])]),_:1})]),p("p",null,[i[11]||(i[11]=n("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[9]||(i[9]=[n("LCTT",-1)])]),_:1}),i[12]||(i[12]=n(" 原创翻译，",-1)),o(t,{href:"http://linux.cn/"},{default:e(()=>[...i[10]||(i[10]=[n("Linux中国",-1)])]),_:1}),i[13]||(i[13]=n(" 荣誉推出",-1))])])}const g=a(f,[["render",x]]);export{c as __pageData,g as default};
